import type {Assessment} from './inventoryRisk';
export type Scenario={quantityOnHand:number;reservedQuantity:number;reorderLevel:number;movementFrequency:number;adjustmentCount:number;daysSinceReplenishment:number};
export type ExperimentInput={operationId:string;scenario:Scenario};
export type FeatureName='available_quantity'|'reserved_quantity'|'movement_frequency'|'reorder_distance'|'adjustment_count'|'days_since_replenishment';
export type Features=Record<FeatureName,number>;
export type StockClass='Normal'|'Reorder Risk'|'Critical Stock Risk';
export type Ranges=Record<FeatureName,{min:number;max:number}>;
export type Provenance={evaluationKind:'synthetic-stock-prototype';origin:'simulated-manual';evaluationOnly:true;operationally_approved:false;independentAccuracyValidated:false;acceptanceSha256:null;humanReviewRequired:true};
export type Prediction=Provenance&{protocol:'inventory-synthetic-inference-1.0';requestId:string;inputSha256:string;features:Features;classOrder:StockClass[];label:StockClass;probabilities:number[];model:'RandomForest';modelSha256:string;servingManifestSha256:string;datasetSha256:string;developmentSha256:string;evaluationSha256:string;processingTimeMs:number;totalProcessingTimeMs:number;outOfRange:FeatureName[]};
export type PredictionExpected=Pick<Prediction,'requestId'|'inputSha256'|'features'|'modelSha256'|'servingManifestSha256'|'datasetSha256'|'developmentSha256'|'evaluationSha256'>&{ranges:Ranges};
export type Readiness={status:'Unavailable';missingFeatures:FeatureName[];reasons:string[];productId:string;productVersion:number;observedAtMs:number};
export type Outcome={state:'Predicted'|'Unavailable'|'Pending'|'Cancelled';operationId:string;experimentId:string|null;replayed:boolean};
export const INVENTORY_AI_PROTOCOL:'inventory-synthetic-inference-1.0';
export const INVENTORY_AI_FEATURES:readonly FeatureName[];
export const INVENTORY_AI_CLASSES:readonly StockClass[];
export const INVENTORY_AI_PROVENANCE:Readonly<Provenance>;
export function validateScenario(value:unknown):Scenario;
export function validateExperimentInput(value:unknown):ExperimentInput;
export function featuresForScenario(value:unknown):Features;
export function canonicalInventoryAI(value:unknown):string;
export function inventoryAIFeaturePayload(value:unknown):string;
export function validateInventoryPrediction(value:unknown,expected:PredictionExpected):Prediction;
export function inventoryAIReadiness(assessment:Assessment):Readiness;
